import 'package:flutter/material.dart';
import 'package:flutter_html/flutter_html.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:jugendkompass_app/presentation/widgets/common/html_inline_image.dart';

// 1000x500 and 40x80 solid PNGs.
const _wide = 'data:image/png;base64,';
const _small = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACgAAABQCAIAAADk7aCWAAAAPklEQVR42u3NMQ0AAAgDsEmZVKTz4oCnSf9m2hcRi8VisVgsFovFYrFYLBaLxWKxWCwWi8VisVgsFovFYvG1OWJgiOnT+EUAAAAASUVORK5CYII=';

Future<Size> _renderedImageSize(WidgetTester tester, String src) async {
  await tester.pumpWidget(
    MaterialApp(
      home: Scaffold(
        body: Center(
          child: SizedBox(
            width: 300,
            child: Html(
              data: '<p>Text davor</p><img src="$src"><p>Text danach</p>',
              extensions: [htmlInlineImageExtension()],
              // Same as the message screen: no body margin.
              style: {'body': Style(margin: Margins.zero, padding: HtmlPaddings.zero)},
            ),
          ),
        ),
      ),
    ),
  );
  // Let the image codec decode.
  await tester.runAsync(() => Future<void>.delayed(const Duration(milliseconds: 200)));
  await tester.pumpAndSettle();
  expect(find.text('Text davor'), findsOneWidget);
  expect(find.text('Text danach'), findsOneWidget);
  return tester.getSize(find.byType(Image));
}

void main() {
  testWidgets('wide image is scaled down to the column width, aspect ratio kept',
      (tester) async {
    final size = await _renderedImageSize(tester, _wide);
    expect(size.width, closeTo(300, 0.5));
    expect(size.height, closeTo(150, 0.5));
  });

  testWidgets('small image keeps its original size (no upscaling)', (tester) async {
    final size = await _renderedImageSize(tester, _small);
    expect(size.width, closeTo(40, 0.5));
    expect(size.height, closeTo(80, 0.5));
  });
}
